"use strict";
window.LocalPlayers = {
  mount(container, el, api, flash) {
    const rightsLabels = LocalPanelComponents.rightsLabels;
    const skillNames = ["Attack", "Defence", "Strength", "Hitpoints", "Ranged", "Prayer", "Magic", "Cooking", "Woodcutting",
      "Fletching", "Fishing", "Firemaking", "Crafting", "Smithing", "Mining", "Herblore", "Agility", "Thieving",
      "Slayer", "Farming", "Runecrafting", "Construction", "Hunter"];
    const skillOrder = [0, 2, 1, 4, 5, 6, 20, 21, 3, 16, 15, 17, 12, 9, 18, 22, 14, 13, 10, 7, 11, 8, 19];
    let players = [];
    let selected;
    let detail;
    let view = "preview";
    let sort = "rights";
    let descending = true;
    let running = false;
    let refreshId = 0;
    let skillIcons = [];
    const search = el("input", { type: "search", placeholder: "Search players", "aria-label": "Search players", oninput: renderList });
    const list = el("div");
    const table = LocalPanelComponents.playersTable(list);
    const pane = el("div", { className: "local-player-pane", hidden: true });
    container.append(el("div", { className: "local-players" }, [
      el("div", { className: "local-player-pane" }, [
        el("div", { className: "local-player-heading" }, [
          search, el("button", { type: "button", text: "Refresh", onclick: refresh }),
        ]),
        list,
      ]), pane,
    ]));
    void api("/panel/skill-icons.json").then(result => {
      if (result.ok) {
        skillIcons = result.body.skills;
        renderDetail();
      }
    }).catch(() => {});

    async function request(path, body) {
      const result = await api(path, body);
      if (!result.ok) throw new Error(result.body?.error || "Could not reach the server.");
      return result.body;
    }

    function renderList() {
      table.render({ players, query: search.value, sort: { key: sort, desc: descending }, selected,
        rightsDisabled: !running,
        onSort(column) {
          descending = sort === column ? !descending : column !== "username";
          sort = column;
          renderList();
        },
        onSelect: player => void choose(player.id),
        onRights: (player, rights) => void change(player.id, "rights", { rights }),
      });
    }

    function renderDetail() {
      pane.hidden = !selected;
      if (pane.hidden) {
        pane.replaceChildren();
        return;
      }
      const player = detail?.player;
      if (!player) {
        pane.replaceChildren(el("p", { className: "local-player-empty", text: "Loading player…" }));
        return;
      }
      const actions = el("details", { className: "local-player-actions" }, [
        el("summary", { text: "Actions" }),
        el("div", null, [
          el("button", { type: "button", text: "Kick", disabled: !running || !player.online, onclick: () => change(player.id, "kick") }),
          el("button", { type: "button", text: player.banned ? "Unban" : "Ban", disabled: !running, onclick: () => change(player.id, "ban", { enabled: !player.banned }) }),
          el("button", { type: "button", text: player.muted ? "Unmute" : "Mute", disabled: !running, onclick: () => change(player.id, "mute", { enabled: !player.muted }) }),
        ]),
      ]);
      const views = el("div", { className: "local-player-view", role: "group", "aria-label": "Player view" },
        ["preview", "json"].map(name => el("button", {
          type: "button", text: name === "json" ? "JSON" : "Preview", "aria-pressed": String(view === name),
          onclick() { view = name; renderDetail(); },
        })));
      const save = detail.save;
      const summary = [
        ["Rights", rightsLabels[player.rights]], ["Combat level", player.combat], ["Total level", player.total],
        ["Kills / deaths", (save.totalKills ?? 0) + " / " + (save.deaths ?? 0)],
        ["Best killstreak", save.highestKillstreak ?? 0], ["Status", player.online ? "Online" : "Offline"],
      ].map(([label, value]) => el("div", null, [el("dt", { text: label }), el("dd", { text: String(value ?? "—") })]));
      const levels = save.skills?.maxLevel;
      const skills = Array.isArray(levels) ? el("div", { className: "local-player-skills", "aria-label": "Skills" },
        skillOrder.filter(index => Number.isFinite(levels[index])).map(index => el("div", {
          className: "local-skill-tile", title: skillNames[index],
        }, [
          skillIcons[index] ? el("img", { src: skillIcons[index], alt: skillNames[index] }) : skillNames[index],
          el("strong", { text: String(levels[index]) }),
        ]))) : null;
      pane.replaceChildren(
        el("div", { className: "local-player-heading" }, [el("strong", { text: player.username }), actions, views]),
        el("div", { className: "local-player-detail" }, [
          view === "json" ? el("pre", { text: JSON.stringify(save, null, 2) }) : el("dl", null, summary),
          view === "preview" ? skills : null,
        ]),
      );
    }

    async function choose(id) {
      selected = id;
      detail = null;
      renderList();
      renderDetail();
      try {
        const result = await request("/api/players/save?name=" + encodeURIComponent(id));
        if (selected === id) { detail = result; renderDetail(); }
      } catch (error) {
        if (selected !== id) return;
        selected = null;
        renderDetail();
        flash("error", error.message);
      }
    }

    async function refresh() {
      const id = ++refreshId;
      try {
        const result = await request("/api/players");
        if (id !== refreshId) return;
        players = result.players;
        if (selected && players.some(player => player.id === selected)) await choose(selected);
        else { selected = null; detail = null; renderList(); renderDetail(); }
      } catch (error) {
        if (id === refreshId) table.error(error.message);
      }
    }

    async function change(id, action, options) {
      try {
        await request("/api/players/action?name=" + encodeURIComponent(id), { action, ...options });
        await refresh();
      } catch (error) {
        renderList();
        flash("error", error.message);
      }
    }

    renderDetail();
    return { refresh, setOnline(online) {
      if (running === online) return;
      running = online;
      renderList();
      renderDetail();
    } };
  },
};
